  window.PortfolioToolArt = id => {
    if (!Object.hasOwn(scenes, id)) return null;
    const scene = document.createElement('span');
    scene.className = 'tool-art-scene';
    scene.setAttribute('aria-hidden', 'true');
    scene.innerHTML = scenes[id];
    return scene;
  };
